        protected void DataGridDespiecePlano_ItemDataBound(object sender, DataGridItemEventArgs e)
        {
            if (e.Item.ItemType == ListItemType.Header)
            {
                for (int i = 0; i < e.Item.Cells.Count; i++)
                {
                    if(i != 0)
                    {
                        if (i == 3) // Suponiendo que la columna "Descripción" es la tercera columna (índice 2)
                        {
                            e.Item.Cells[i].CssClass = "descripcion-header";
                        }
                        else
                        {
                            e.Item.Cells[i].CssClass = "resizable-header";
                        }
                    }
                   
                }
            }


            if (e.Item.ItemType == ListItemType.Item || e.Item.ItemType == ListItemType.AlternatingItem)
            {
                DatosFiltrados datos = (DatosFiltrados)e.Item.DataItem;

                if (datos.Tipo == "Total" && datos.Titulo == "<b>Totales</b>")
                {
                    e.Item.BackColor = System.Drawing.ColorTranslator.FromHtml("#7aeaff");
                }
                else if (!string.IsNullOrEmpty(datos.ID))
                {
                    if (datos.RevisadoDibujo == true)
                    {
                        e.Item.BackColor = System.Drawing.ColorTranslator.FromHtml("#47ca4b");
                        e.Item.ForeColor = System.Drawing.ColorTranslator.FromHtml("#000000");
                    }
                }

                if (datos.ValorUnd == "0")
                {
                    for (int i = 4; i <= 8; i++) // Pinta las celdas de la 4 a la 8 (índices 3 a 7)
                    {
                        e.Item.Cells[i].BackColor = System.Drawing.ColorTranslator.FromHtml("#FC0026");
                        e.Item.Cells[i].ForeColor = System.Drawing.ColorTranslator.FromHtml("#ffffff");
                    }

                    Session["ValorUnd"] = "1";
                }

                //Alienar celdas el centro               
                e.Item.Cells[4].HorizontalAlign = HorizontalAlign.Center;
                e.Item.Cells[5].HorizontalAlign = HorizontalAlign.Center;
                e.Item.Cells[6].HorizontalAlign = HorizontalAlign.Center;


                // Formatear y alinear SubTotal a la derecha
                decimal valorUnd;
                if (decimal.TryParse(datos.ValorUnd, out valorUnd))
                {
                    e.Item.Cells[7].Text = valorUnd.ToString("N0"); // Formato de número con 2 decimales
                    e.Item.Cells[7].HorizontalAlign = HorizontalAlign.Right; // Alinear a la derecha
                }



                decimal subTotal;
                if (decimal.TryParse(datos.SubTotal, out subTotal))
                {
                    e.Item.Cells[8].Text = subTotal.ToString("N0");
                    e.Item.Cells[8].HorizontalAlign = HorizontalAlign.Right;
                }


                if (datos.Tipo == "Total" && decimal.TryParse(datos.SubTotal.Replace("<b>", "").Replace("</b>", ""), out decimal subTotal1))
                {
                    e.Item.Cells[8].Text = $"<b>{subTotal1.ToString("N0")}</b>";
                    e.Item.Cells[8].HorizontalAlign = HorizontalAlign.Right;
                    e.Item.Cells[8].Font.Bold = true;
                    e.Item.Cells[8].Font.Size = 11;
                }

                // Mantener el enfoque en la fila seleccionada
                if (Session["SelectedRowIndex"] != null && e.Item.ItemIndex == Convert.ToInt32(Session["SelectedRowIndex"]))
                {  
                    e.Item.Attributes["id"] = "row_" + e.Item.ItemIndex;
                    Session.Remove("SelectedRowIndex");
                }


            }
        }

        protected void DataGridDespiecePlano_LinkButton(object source, DataGridCommandEventArgs e)
        {

            if (e.CommandName == "VerPlano")
            {
                int rowIndex = Convert.ToInt32(e.CommandArgument);
                DataGridItem row = DataGridDespiecePlano.Items[rowIndex];


                foreach (DataGridItem item in DataGridDespiecePlano.Items)
                {
                    if (item != row)
                    {
                        item.CssClass = ""; // Elimina la clase CSS de las filas no seleccionadas
                    }
                }

                //se usa Para darle un color a la fila seleccionada  
                e.Item.CssClass = "fila-seleccionada";
                string ID = row.Cells[2].Text;
                string Descri = row.Cells[3].Text;
                string Ancho = row.Cells[5].Text;
                string cantidad = row.Cells[6].Text;
                string revisado = row.Cells[10].Text;
                string Id_Panel = row.Cells[9].Text;
                LlenarDataGridObjeto(ID);


                Session["SelectedRowIndex"] = rowIndex;



                // Se envia la descripcion como parametro de busqueda al tap objetos  y se refresca el panel deobjetos 
                txtCantidad.Text = cantidad;
                tbCriterio.Text = Id_Panel;
                PanelObjeto.Update();

                btnCambiar.Enabled = true;
                btnCambiar.CssClass = "btn btn-outline-secondary";

                Session["IdObjetoEliminarSession"] = ID;
                BtnQuiObjPla.Enabled = true;
                BtnQuiObjPla.CssClass = "btn btn-sm shadow button-enabled ColorAzulActivo";


                ObjetoEliminar.InnerText = Descri;
                anchoEliminar.InnerText = Ancho;

                // Asignar ID único a la fila
                row.Attributes["id"] = "row_" + rowIndex;

                // Llamar a la función JavaScript para enfocar y desplazar la fila
                ScriptManager.RegisterStartupScript(this, GetType(), "scrollToRow", "focusAndScrollToRow('row_" + rowIndex + "');", true);



                if (row.Cells[2].Text == Session["ID_Item"]?.ToString())
                {
                    // Incrementar la variable de sesión "ClickCount" en el servidor
                    int clickCount = Convert.ToInt32(Session["ClickCount3"]) + 1;
                    Session["ClickCount3"] = clickCount;

                    // se valida si es el segundo click en la misma fila 
                    if (clickCount == 2)
                    {

                        // Reiniciar la variable de sesión "ClickCount" a 0 para la próxima interacción                        
                        Session.Remove("ID_Item");
                        Session.Remove("ClickCount3");

                        if (Session["Departamento"].ToString().ToUpper() == "DISEÑO" || Session["Departamento"].ToString().ToUpper() == "DESARROLLO DE PRODUCTO")
                        {
                            // cambiar de estado;
                            if (revisado == "True")
                            {
                                CambiarEstadoRevisado(ID, 0);
                            }
                            else
                            {
                                CambiarEstadoRevisado(ID, 1);
                            }

                            Cargar_Despiece_Plano();

                            int selectedRowIndex = Convert.ToInt32(Session["SelectedRowIndex"]);
                            ScriptManager.RegisterStartupScript(this, GetType(), "scrollToRow", $"focusAndScrollToRow('row_{selectedRowIndex}');", true);
                        }


                    }

                }
                else
                {
                    // Si el clic no es en la misma fila, reiniciar la variable de sesión "ClickCount" a 1
                    Session["ClickCount3"] = 1;
                    Session["ID_Item"] = row.Cells[2].Text;

                }




            }
        }


        private bool CambiarEstadoRevisado(string ID_Numerico, int Estado)
        {
            string connectionString = ConfigurationManager.ConnectionStrings[CadenaConexionSID].ConnectionString;
            string sSql = "UPDATE tblPlano_Panel SET RevisadoDibujo = @Estado WHERE Id_Plano = @IdPlano AND Id_PanelNum = @Id_PanelNum1";

            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                connection.Open();

                using (SqlCommand cmd = new SqlCommand(sSql, connection))
                {
                    // Ajusta los valores según los nombres de columnas reales en tu DataRow
                    cmd.Parameters.AddWithValue("@IdPlano", txtPlano.Text);
                    cmd.Parameters.AddWithValue("@Id_PanelNum1", ID_Numerico);
                    cmd.Parameters.AddWithValue("@Estado", Estado);

                    int filaAfectada = cmd.ExecuteNonQuery();
                    return filaAfectada > 0;

                }
            }
        }

