                                  "VALUES (@cocNIT, @cocConsecutivoContacto, @cocSede, @cocDireccion,@cocCiudad,@cocNombre,@cocTelefono,@cocCelular,@cocMail," +
                                  "@cocFechaCreacion,@cocUltimaActualizacion)";


