                              "ON tblAcabado.ID_Acabado = tblOTAcabados.ID_Acabado " +
                              "WHERE (((tblOTAcabados.Id_OT)= @IdOT) AND ((tblOTAcabados.Consecutivo_Pedido)= @Pedido)) ";

