                    cmd.Parameters.AddWithValue("@IdOT", tbOT.Text);
                    cmd.Parameters.AddWithValue("@Pedido", ddlNumbers.SelectedItem.Text);

                    using (SqlDataAdapter adapter = new SqlDataAdapter(cmd))
